detaileddescription.para:
The SPI header file should be included in an application as follows: #include<ti/drivers/SPI.h>
#include<ti/drivers/spi/SPIWFF3DMA.h>
#include<ti/drivers/dma/DMAWFF3.h>

Receive 100 bytes over SPI in SPI_MODE_BLOCKING. SPI_Handlehandle;SPI_Paramsparams;SPI_Transactiontransaction;uint8_t
rxBuf[100];//Receivebuffer

//InitSPIandspecifynon-defaultparametersSPI_Params_init(&params);
params.bitRate=1000000;params.frameFormat=SPI_POL1_PHA1;
params.mode=SPI_PERIPHERAL;

//Configurethetransactiontransaction.count=100;transaction.txBuf=
NULL;transaction.rxBuf=rxBuf;

//OpentheSPIandperformthetransferhandle=SPI_open(CONFIG_SPI,
&params);SPI_transfer(handle,&transaction);

This use case will perform a transfer in SPI_MODE_BLOCKING until the wanted amount of bytes is transferred or until chip select is deasserted by the SPI controller. This SPI_transfer() call can be used when unknown amount of bytes shall be transferred. Note: The partial return is also possible in SPI_MODE_CALLBACK mode. Note: Polling transfers are not available when using return partial mode. SPI_Handlehandle;SPI_Paramsparams;SPI_Transactiontransaction;uint8_t
rxBuf[100];//Receivebuffer

//InitSPIandspecifynon-defaultparametersSPI_Params_init(&params);
params.bitRate=1000000;params.frameFormat=SPI_POL1_PHA1;
params.mode=SPI_PERIPHERAL;

//Configurethetransactiontransaction.count=100;transaction.txBuf=
NULL;transaction.rxBuf=rxBuf;

//OpentheSPIandinitiatethepartialreadhandle=SPI_open(CONFIG_SPI,
&params);

//EnableRETURN_PARTIALSPI_control(handle,
SPIWFF3DMA_RETURN_PARTIAL_ENABLE,NULL);

//BegintransferSPI_transfer(handle,&transaction);

This use case will configure the SPI driver to transfer continuously in SPI_MODE_CALLBACK, 16 bytes at the time and echoing received data after every 16 bytes. //CallbackfunctionstaticvoidtransferCallback(SPI_Handlehandle,
SPI_Transaction*transaction)
{
//Startanothertransfer
SPI_transfer(handle,transaction);
}

staticvoidtaskFxn(uintptr_ta0,uintptr_ta1)
{
SPI_Handlehandle;
SPI_Paramsparams;
SPI_Transactiontransaction;
uint8_tbuf[16];//Receiveandtransmitbuffer

//InitSPIandspecifynon-defaultparameters
SPI_Params_init(&params);
params.bitRate=1000000;
params.frameFormat=SPI_POL1_PHA1;
params.mode=SPI_PERIPHERAL;
params.transferMode=SPI_MODE_CALLBACK;
params.transferCallbackFxn=transferCallback;

//Configurethetransaction
transaction.count=16;
transaction.txBuf=buf;
transaction.rxBuf=buf;

//OpentheSPIandinitiatethefirsttransfer
handle=SPI_open(CONFIG_SPI,&params);
SPI_transfer(handle,&transaction);

//Waitforever
while(true);
}

This use case will configure a SPI controller to send the data in txBuf while receiving data to rxBuf in BLOCKING_MODE. SPI_Handlehandle;SPI_Paramsparams;SPI_Transactiontransaction;uint8_t
txBuf[]="HelloWorld";//Transmitbufferuint8_trxBuf[11];
//Receivebuffer

//InitSPIandspecifynon-defaultparametersSPI_Params_init(&params);
params.bitRate=1000000;params.frameFormat=SPI_POL1_PHA1;
params.mode=SPI_CONTROLLER;

//Configurethetransactiontransaction.count=sizeof(txBuf);
transaction.txBuf=txBuf;transaction.rxBuf=rxBuf;

//OpentheSPIandperformthetransferhandle=SPI_open(CONFIG_SPI,
&params);SPI_transfer(handle,&transaction);

Below is an example of queueing three transactions //SPIalreadyopenedincallbackmodeSPI_Transactiont0,t1,t2;

t0.txBuf=txBuff0;t0.rxBuf=rxBuff0;t0.count=2000;

t1.txBuf=txBuff1;t1.rxBuf=rxBuff1;t1.count=1000;

t2.txBuf=txBuff2;t2.rxBuf=NULL;t2.count=1000;

booltransferOk=false;

if(SPI_transfer(spiHandle,&t0)){if(SPI_transfer(spiHandle,&t1)){
transferOk=SPI_transfer(spiHandle,&t2);
}
}
}

###Ensurelowpowerduringinactiveperiods@anchorUSE_CASE_LPWR_WFF3#
ExternalhardwareconnectedontheSPI,i.e.SPIcontroller/peripheral,
mighthaveconfiguredapullononeormoreoftheSPIlines.Dependenton
thehardware,itmightconflictwiththepullusedfortheWi-FiF3
deviceSPI.Toavoidincreasedleakageandensurethelowestpossiblepower
consumptionwhentheSPIisinactive,theapplicationmustconfigurea
matchingpullontheSPIIOs.Anexampleofhowthiscanbedoneisshown
below.

@code
SPI_Paramsparams;SPI_Transactiontransaction;uint8_ttxBuf[]=
"Heartbeat";//Transmitbufferuint8_trxBuf[9];//
Receivebufferuint32_tsleepDurationMs=100;

//InitSPIandspecifynon-defaultparametersSPI_Params_init(&params);
params.bitRate=1000000;params.frameFormat=SPI_POL1_PHA1;
params.mode=SPI_CONTROLLER;

//Configurethetransactiontransaction.count=sizeof(txBuf);
transaction.txBuf=txBuf;transaction.rxBuf=rxBuf;

//OpentheSPIandperformthetransferhandle=SPI_open(CONFIG_SPI_0,
&params);

//ApplylowpowersleeppullconfigforPOCI
GPIO_setConfig(CONFIG_GPIO_SPI_0_POCI,GPIO_CFG_IN_PU);

//Doforeverwhile(1){//TransferdataSPI_transfer(handle,
&transaction);//SleepTask_sleep(sleepDurationMs*100);
}
